#!/usr/bin/env python3
"""Database packaging and verification for the ci-beta pre-release (beta-prerelease.yml).

  package       build canary-bots-beta-sql/ : the upgrade files since a baseline release,
                upgrade.sh, UPGRADE.md, and the full fresh-install sources
  compare       fail unless two databases have identical tables, columns, indexes,
                constraints and table contents
  fresh-readme  IMPORT.txt for the fresh-install database zip
  notes         the pre-release notes (markdown)

How an existing install upgrades (the facts this script encodes):
  * database/bots/import.sh lists, in order, every SQL file a FRESH install runs. Files
    added to that list since a release are the upgrade for that release. They are written
    to be safe on an existing database (CREATE TABLE IF NOT EXISTS, guarded ALTERs).
  * schema.sql changes do not reach an existing database by themselves; the bot files
    above carry the matching ALTERs (16_runtime_compatibility.sql widens the columns the
    newer schema.sql declares wider). The fresh-vs-upgraded check proves nothing is missed.
  * data-otservbr-global/migrations/<N>.lua run at server start while
    server_config.db_version < N. A NEW migration file upgrades an existing database on
    the next boot; an EDITED one never re-runs on a database already past it.
"""
import argparse
import difflib
import os
import re
import shutil
import subprocess
import sys

BOTS = os.path.join("database", "bots")
MIGRATIONS = os.path.join("data-otservbr-global", "migrations")
SCHEMA_DDL = "00_bot_schema.sql"
UPGRADE_ONLY = re.compile(r"^9\d_[A-Za-z0-9_]+\.sql$")


def import_list(path):
    text = open(path, encoding="utf-8").read()
    m = re.search(r"^FILES=\(\s*\n(.*?)^\)", text, re.S | re.M)
    if not m:
        sys.exit(f"no FILES=( ... ) array in {path}")
    return [ln.strip() for ln in m.group(1).splitlines() if ln.strip() and not ln.strip().startswith("#")]


def norm(path):
    with open(path, "rb") as fh:
        return fh.read().replace(b"\r\n", b"\n")


UPGRADE_SH = r"""#!/usr/bin/env bash
# Upgrade an existing Canary Bots database from {baseline} to this build.
# Generated by .github/beta/beta_sql.py. Stop the server first, and back up:
#   mysqldump -u root -p canary > canary-backup.sql
#
#   DB_HOST=127.0.0.1 DB_USER=root DB_PASS=secret DB_NAME=canary ./upgrade.sh
#
# Every file is safe to re-run.
set -euo pipefail
DB_HOST="${{DB_HOST:-127.0.0.1}}"
DB_PORT="${{DB_PORT:-3306}}"
DB_USER="${{DB_USER:-root}}"
DB_PASS="${{DB_PASS:-}}"
DB_NAME="${{DB_NAME:-canary}}"
DIR="$(cd "$(dirname "${{BASH_SOURCE[0]}}")" && pwd)"
args=(-h "$DB_HOST" -P "$DB_PORT" -u "$DB_USER")
[ -n "$DB_PASS" ] && args+=("-p$DB_PASS")
args+=("$DB_NAME")
FILES=(
{files}
)
for f in "${{FILES[@]}}"; do
  echo ">> applying $f"
  mysql "${{args[@]}}" < "$DIR/upgrade/$f"
done
echo "Done: {count} upgrade file(s) applied to '$DB_NAME'."
"""


def cmd_package(a):
    cur_list = import_list(os.path.join(a.repo, BOTS, "import.sh"))
    base_list = import_list(os.path.join(a.baseline, BOTS, "import.sh"))
    new = [f for f in cur_list if f not in base_list]
    gone = [f for f in base_list if f not in cur_list]
    changed = [f for f in cur_list if f in base_list
               and os.path.exists(os.path.join(a.baseline, BOTS, f))
               and norm(os.path.join(a.repo, BOTS, f)) != norm(os.path.join(a.baseline, BOTS, f))]
    on_disk = sorted(f for f in os.listdir(os.path.join(a.repo, BOTS)) if f.endswith(".sql"))
    # 00_bot_schema.sql is CREATE TABLE IF NOT EXISTS only: when it changed, re-run it FIRST so
    # the tables it gained since the baseline reach an existing database.
    rerun = [f for f in changed if f == SCHEMA_DDL]
    # Upgrade-only reconciliation scripts (9N_*.sql): never in import.sh (a fresh install does not
    # need them), new since the baseline, run LAST. Idempotent by the same contract.
    upgrade_only = sorted(f for f in on_disk if UPGRADE_ONLY.match(f) and f not in cur_list
                          and not os.path.exists(os.path.join(a.baseline, BOTS, f)))
    new = rerun + new + upgrade_only
    unlisted = [f for f in on_disk if f not in cur_list and not UPGRADE_ONLY.match(f)
                and not re.search(r"(\.before|_rollback)\.sql$", f)]
    for f in unlisted:
        print(f"::warning::{BOTS}/{f} is not in import.sh: a fresh install never runs it")
    for f in gone:
        print(f"::warning::{f} was in the {a.baseline_tag} import.sh and is not any more")
    mig_cur = {f for f in os.listdir(os.path.join(a.repo, MIGRATIONS)) if f.endswith(".lua")}
    mig_dir_base = os.path.join(a.baseline, MIGRATIONS)
    mig_base = {f for f in os.listdir(mig_dir_base) if f.endswith(".lua")} if os.path.isdir(mig_dir_base) else set()
    mig_new = sorted(mig_cur - mig_base, key=lambda f: int(re.sub(r"\D", "", f) or 0)) if mig_base else []
    mig_changed = sorted((f for f in mig_cur & mig_base
                          if norm(os.path.join(a.repo, MIGRATIONS, f)) != norm(os.path.join(mig_dir_base, f))),
                         key=lambda f: int(re.sub(r"\D", "", f) or 0))
    schema_changed = norm(os.path.join(a.repo, "schema.sql")) != norm(os.path.join(a.baseline, "schema.sql"))

    root = os.path.join(a.out, "canary-bots-beta-sql")
    shutil.rmtree(root, ignore_errors=True)
    os.makedirs(os.path.join(root, "upgrade"))
    for f in new:
        shutil.copyfile(os.path.join(a.repo, BOTS, f), os.path.join(root, "upgrade", f))
    with open(os.path.join(root, "upgrade.sh"), "w", newline="\n") as fh:
        fh.write(UPGRADE_SH.format(baseline=a.baseline_tag, files="\n".join("  " + f for f in new), count=len(new)))
    os.chmod(os.path.join(root, "upgrade.sh"), 0o755)
    fresh = os.path.join(root, "fresh")
    os.makedirs(os.path.join(fresh, "database"))
    shutil.copyfile(os.path.join(a.repo, "schema.sql"), os.path.join(fresh, "schema.sql"))
    shutil.copytree(os.path.join(a.repo, BOTS), os.path.join(fresh, "database", "bots"))
    with open(os.path.join(root, "upgrade-files.txt"), "w", newline="\n") as fh:
        fh.write(f"Upgrade from {a.baseline_tag}: {len(new)} SQL file(s), in this order:\n\n")
        for f in new:
            fh.write(f"- `{f}`\n")
        if mig_new and upgrade_only:
            fh.write(f"\nNew Lua migrations {', '.join(mig_new)}: already applied by {', '.join(upgrade_only)} "
                     "(it sets db_version), so the server does not run them again.\n")
        elif mig_new:
            fh.write(f"\nNew Lua migrations (run by the server at its next start): {', '.join(mig_new)}\n")
        fh.write("\n")
    md = [f"# Upgrading a Canary Bots database from `{a.baseline_tag}`", "",
          "1. **Stop the server** and **back up** the database: `mysqldump -u root -p canary > canary-backup.sql`.",
          "2. Run the upgrade files, in order. With a shell:", "",
          "   ```bash", "   DB_HOST=127.0.0.1 DB_USER=root DB_PASS=yourpass DB_NAME=canary ./upgrade.sh", "   ```", "",
          "   Without one (MySQL Workbench, HeidiSQL, ...), run these files from `upgrade/` against your",
          "   database, in this order:", ""]
    md += [f"   {i}. `{f}`" for i, f in enumerate(new, 1)] or ["   (none: the database layout did not change)"]
    md += ["",
           "3. Replace the binaries (and the `data/`, `data-otservbr-global/` folders from the runtime tarball).",
           "   Keep your `config.lua`; compare it with the new `config.lua.dist` for new keys (every bot key has a",
           "   default, so a missing key only means the default).",
           "4. Start the server. It applies any new `data-otservbr-global/migrations/*.lua` by itself"
           + ((f" ({', '.join(mig_new)} are new since {a.baseline_tag}; {', '.join(upgrade_only)} above"
               " already applied them).") if mig_new and upgrade_only else
              (f" (new since {a.baseline_tag}: {', '.join(mig_new)})." if mig_new
               else f" (none are new since {a.baseline_tag}).")),
           "",
           "Every upgrade file is safe to run twice. The CI run that built this zip applied it to the",
           f"`{a.baseline_tag}` release database and proved the result identical (tables, columns, indexes,",
           "constraints and contents) to a fresh install of this build.", "",
           "**Never** import `fresh/` or the fresh-install database zip over an existing install: the seed",
           "files use plain `INSERT`s and the dump replaces your accounts and characters.", ""]
    seeds = [f for f in changed if f not in rerun]
    if seeds:
        md += [f"Seed files that changed since {a.baseline_tag} (they affect fresh installs only and are **not**",
               "re-applied to an existing database): " + ", ".join(f"`{f}`" for f in seeds), ""]
    if mig_changed:
        md += [f"Lua migrations edited since {a.baseline_tag} (they never re-run on a database already past them;",
               "the upgrade files above carry the same change): " + ", ".join(f"`{f}`" for f in mig_changed), ""]
    if schema_changed:
        md += [f"`schema.sql` changed since {a.baseline_tag}. Do not re-import it: the upgrade files carry the",
               "matching `ALTER`s.", ""]
    md += ["## Contents", "",
           "- `upgrade/`, `upgrade.sh`: the upgrade above.",
           "- `fresh/`: `schema.sql` + `database/bots/` of this build, for a **new** install",
           "  (`schema.sql` first, then `database/bots/import.sh`).", ""]
    with open(os.path.join(root, "UPGRADE.md"), "w", newline="\n", encoding="utf-8") as fh:
        fh.write("\n".join(md))
    print(f"upgrade files: {new}")
    print(f"changed seed files: {changed}; new migrations: {mig_new}; edited migrations: {mig_changed}; "
          f"schema.sql changed: {schema_changed}")


def mysql(a, db, sql):
    r = subprocess.run(["mysql", "-h", a.host, "-u", a.user, "-N", "-B", "--default-character-set=utf8mb4",
                        "-e", sql, db], capture_output=True, text=True)
    if r.returncode:
        sys.exit(f"mysql failed on {db}: {r.stderr}")
    return [ln.split("\t") for ln in r.stdout.splitlines()]


def snapshot(a, db):
    q = lambda sql: [tuple(r) for r in mysql(a, db, sql.replace("@DB", f"'{db}'"))]  # noqa: E731
    snap = {
        "tables": q("SELECT table_name, engine, table_collation, row_format FROM information_schema.tables "
                    "WHERE table_schema=@DB ORDER BY 1"),
        "columns": q("SELECT table_name, ordinal_position, column_name, column_type, is_nullable, "
                     "IFNULL(column_default,'<NULL>'), extra, IFNULL(character_set_name,''), IFNULL(collation_name,'') "
                     "FROM information_schema.columns WHERE table_schema=@DB ORDER BY 1, 2"),
        "indexes": q("SELECT table_name, index_name, seq_in_index, column_name, non_unique, IFNULL(sub_part,''), "
                     "index_type FROM information_schema.statistics WHERE table_schema=@DB ORDER BY 1, 2, 3"),
        "constraints": q("SELECT tc.table_name, tc.constraint_name, tc.constraint_type, IFNULL(rc.referenced_table_name,''), "
                         "IFNULL(rc.update_rule,''), IFNULL(rc.delete_rule,'') FROM information_schema.table_constraints tc "
                         "LEFT JOIN information_schema.referential_constraints rc ON rc.constraint_schema=tc.constraint_schema "
                         "AND rc.constraint_name=tc.constraint_name WHERE tc.table_schema=@DB ORDER BY 1, 2"),
        "triggers_routines": q("SELECT 'trigger', trigger_name, event_object_table, action_statement FROM information_schema.triggers "
                               "WHERE trigger_schema=@DB UNION ALL SELECT 'routine', routine_name, routine_type, routine_definition "
                               "FROM information_schema.routines WHERE routine_schema=@DB ORDER BY 1, 2"),
    }
    tables = [t[0] for t in snap["tables"]]
    sums = []
    for t in tables:
        cnt = mysql(a, db, f"SELECT COUNT(*) FROM `{t}`")[0][0]
        chk = mysql(a, db, f"CHECKSUM TABLE `{t}`")[0][1]
        sums.append((t, cnt, chk))
    snap["contents"] = sums
    return snap


CREATE_RE = re.compile(r"CREATE\s+TABLE\s+(?:IF\s+NOT\s+EXISTS\s+)?`?([A-Za-z0-9_]+)`?", re.I)


def expected_tables(repo):
    """Every table the fresh install's SQL creates: schema.sql + the import.sh files."""
    names = set()
    paths = [os.path.join(repo, "schema.sql")]
    imp = os.path.join(repo, BOTS, "import.sh")
    if os.path.exists(imp):
        paths += [os.path.join(repo, BOTS, f) for f in import_list(imp)]
    for path in paths:
        if os.path.exists(path):
            names.update(n.lower() for n in CREATE_RE.findall(norm(path).decode("utf-8", "replace")))
    return names


def cmd_compare(a):
    A, B = snapshot(a, a.a), snapshot(a, a.b)
    bad = 0
    lines = [f"### `{a.a}` vs `{a.b}`", ""]
    # Identical is not enough: a table missing from BOTH sides compares equal. Every table the
    # fresh-install SQL of this tree creates must exist on each side.
    want = expected_tables(a.repo)
    for db, snap in ((a.a, A), (a.b, B)):
        have = {t[0].lower() for t in snap["tables"]}
        missing = sorted(want - have)
        if missing:
            bad = 1
            print(f"::error::{db} lacks {len(missing)} table(s) the fresh-install SQL creates: {', '.join(missing)}")
            lines.append(f"- **`{db}` lacks: {', '.join(missing)}**")
    lines.append(f"- expected tables (schema.sql + import.sh files): {len(want)}")
    for k in A:
        if A[k] == B[k]:
            lines.append(f"- {k}: identical ({len(A[k])} rows)")
            continue
        bad = 1
        lines.append(f"- **{k}: DIFFERENT**")
        diff = list(difflib.unified_diff(["\t".join(r) for r in A[k]], ["\t".join(r) for r in B[k]],
                                         a.a, a.b, lineterm="", n=0))
        print(f"::error::{k} differ between {a.a} and {a.b}")
        print("\n".join(diff[:200]))
    tables = len(A["tables"])
    rows = sum(int(r[1]) for r in A["contents"])
    lines.append(f"- {tables} tables, {rows} rows in `{a.a}`")
    print("\n".join(lines))
    if a.summary:
        with open(a.summary, "a", encoding="utf-8") as fh:
            fh.write("\n".join(lines) + "\n\n")
    sys.exit(bad)


def cmd_fresh_readme(a):
    print(f"""canary-bots-beta-fresh.sql -- a complete database for a NEW Canary Bots install.

It is schema.sql + database/bots/import.sh of this build, already applied (the god
account, the bot account and its 997 bots, market prices, bot houses). Import it into an
EMPTY database:

  mysql -u root -p -e "CREATE DATABASE canary DEFAULT CHARACTER SET utf8mb3;"
  mysql -u root -p canary < canary-bots-beta-fresh.sql

Then set mysqlHost/mysqlUser/mysqlPass/mysqlDatabase in config.lua. The server applies
its Lua migrations (data-otservbr-global/migrations) on the first start.

Default admin login: account @god / password god12345 -- change it after the first login.

Already running a Canary Bots database (e.g. {a.baseline_tag})? Do NOT import this file:
it replaces your accounts and characters. Use canary-bots-beta-sql.zip (UPGRADE.md).
""")


def cmd_notes(a):
    info = dict(ln.strip().split("=", 1) for ln in open(a.build_info) if "=" in ln)
    upgrade = open(a.upgrade_files, encoding="utf-8").read().strip()
    short = a.sha[:9]
    base = f"https://github.com/{a.repo}/releases/download"
    print(f"""Automated build of the `beta` branch at commit [`{short}`](https://github.com/{a.repo}/commit/{a.sha}) ({a.date}).

**Untested development build**, rebuilt on every push to `beta`. For a tested package use a
versioned [release](https://github.com/{a.repo}/releases) (latest: `{a.baseline_tag}`).

| Asset | What it is |
|---|---|
| `canary-bots-beta-linux-x64.tar.gz` | `canary` + `libbot_engine.so` (Linux x86-64). Built on Ubuntu 22.04 with GCC 13: needs glibc ≥ 2.35 and the GCC 13 `libstdc++` (`{info.get('glibcxx', '?')}`; Ubuntu 24.04 has it, Ubuntu 22.04 needs `ppa:ubuntu-toolchain-r/test` → `libstdc++6`). Built for `-march=x86-64-v2` (any x86-64 CPU since ~2009; no AVX required). Bot engine ABI tag `{info.get('abi_tag', '?')[:16]}…` |
| `canary-bots-beta-win64.zip` | `canary.exe` (Windows 10/11 x64). The bot engine is linked in; no DLLs, no VC++ redistributable. No `/cavebot reload` on Windows: restart instead. |
| `canary-bots-beta-runtime.tar.gz` | `data/`, `data-otservbr-global/`, `database/`, `schema.sql`, `config.lua.dist`, `key.pem`. Extract next to the binaries. **No world map** (see below). |
| `canary-bots-beta-db-fresh.zip` | `canary-bots-beta-fresh.sql`: a ready database for a **new install** (`schema.sql` + `database/bots` already applied). |
| `canary-bots-beta-sql.zip` | `UPGRADE.md`, `upgrade.sh` + `upgrade/`: the SQL to **upgrade** an existing `{a.baseline_tag}` database; `fresh/`: the SQL sources of a new install. |
| `SHA256SUMS.txt` | checksums of the above |

### New install

```bash
mkdir canary-bots && cd canary-bots
BASE={base}/ci-beta
wget $BASE/canary-bots-beta-linux-x64.tar.gz $BASE/canary-bots-beta-runtime.tar.gz $BASE/canary-bots-beta-db-fresh.zip
tar -xzf canary-bots-beta-runtime.tar.gz
tar -xzf canary-bots-beta-linux-x64.tar.gz --strip-components=1
wget -O data-otservbr-global/world/otservbr.otbm \\
  https://github.com/opentibiabr/canary/releases/download/v3.1.0/otservbr.otbm
unzip canary-bots-beta-db-fresh.zip
mysql -u root -p -e "CREATE DATABASE canary DEFAULT CHARACTER SET utf8mb3;"
mysql -u root -p canary < canary-bots-beta-fresh.sql
cp config.lua.dist config.lua   # then set mysql* and ip
./canary
```

Windows: the same runtime, map and database steps, then `canary.exe` from the win64 zip.
Default admin login: account **`@god`** / password **`god12345`**: change it after the first login.

### Upgrading an existing `{a.baseline_tag}` install

1. Stop the server and back up the database (`mysqldump`).
2. Extract `canary-bots-beta-sql.zip` and run `upgrade.sh` (or the files in `upgrade/`, in the order `UPGRADE.md` lists).
3. Replace the binaries, `data/` and `data-otservbr-global/` (keep your map and `config.lua`; compare it with `config.lua.dist`).
4. Start the server: it applies any new Lua migration by itself.

Never import the fresh-install database over an existing install: it replaces your accounts and characters.

{upgrade}

This run verified the upgrade: the `{a.baseline_tag}` release database + `upgrade.sh` and a fresh install of this
build have identical tables, columns, indexes, constraints and contents, and the Linux build booted against the
fresh database (Lua migrations, bot engine, bot startup).
""")


def main():
    ap = argparse.ArgumentParser()
    sub = ap.add_subparsers(dest="cmd", required=True)
    p = sub.add_parser("package")
    p.add_argument("--baseline-tag", required=True)
    p.add_argument("--baseline", required=True)
    p.add_argument("--repo", default=".")
    p.add_argument("--out", required=True)
    p = sub.add_parser("compare")
    p.add_argument("--host", default="127.0.0.1")
    p.add_argument("--user", default="root")
    p.add_argument("--a", required=True)
    p.add_argument("--b", required=True)
    p.add_argument("--summary")
    p.add_argument("--repo", default=".", help="tree whose fresh-install SQL names the expected tables")
    p = sub.add_parser("fresh-readme")
    p.add_argument("--baseline-tag", required=True)
    p = sub.add_parser("notes")
    for k in ("repo", "sha", "date", "baseline-tag", "build-info", "upgrade-files"):
        p.add_argument("--" + k, required=True)
    a = ap.parse_args()
    {"package": cmd_package, "compare": cmd_compare, "fresh-readme": cmd_fresh_readme, "notes": cmd_notes}[a.cmd](a)


if __name__ == "__main__":
    main()
